import { useEffect, useState } from "react";

export function LearnerProfile({ learnerId }) {
  const [result, setResult] = useState({ status: "loading" });
  const [attempt, setAttempt] = useState(0);            // bump to retry.

  useEffect(() => {
    const controller = new AbortController();
    setResult({ status: "loading" });
    fetch(`/api/learners/${encodeURIComponent(learnerId)}`, { signal: controller.signal })
      .then((r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json();
      })
      .then((data) => setResult({ status: "success", data }))
      .catch((e) => {
        if (e.name !== "AbortError") setResult({ status: "error", message: e.message });
      });
    return () => controller.abort();                   // old request can't win.
  }, [learnerId, attempt]);

  if (result.status === "loading") return <p role="status">Loading profile...</p>;
  if (result.status === "error")
    return <p role="alert">Couldn't load. <button type="button" onClick={() => setAttempt((n) => n + 1)}>Retry</button></p>;
  return <h2>{result.data.name}</h2>;
}
